const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sichuanBasin = ee.Geometry.Rectangle([103, 29, 107, 32]);
  const startYear = 2006;
  const endYear = 2020;
  const aodBand = 'Optical_Depth_Land_And_Ocean';

  // 2. Data Acquisition & Processing Function
  // MODIS Terra Aerosol 5-Min L2 Swath 10km
  const collectionId = 'MODIS/061/MOD04_L2';

  // Function to get mean AOD for a given year.
  // It filters by date and geometry, masks for high-quality pixels, and calculates the mean.
  const getMeanAod = function(year) {
    const startDate = ee.Date.fromYMD(year, 1, 1);
    const endDate = ee.Date.fromYMD(year, 12, 31);

    let collection = ee.ImageCollection(collectionId)
      .filterBounds(sichuanBasin)
      .filterDate(startDate, endDate)
      .select([aodBand, 'Land_Ocean_Quality_Flag']);

    // Check if the initial collection is empty
    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      return { mean: null, pixels: 0, images: 0, year: year };
    }

    // Mask for the highest quality retrievals over land (QA flag = 3)
    const maskQuality = function(image) {
      const qa = image.select('Land_Ocean_Quality_Flag');
      const aod = image.select(aodBand).multiply(0.001); // Apply scale factor
      const mask = qa.eq(3); // 3 = Very Good quality over land
      return aod.updateMask(mask).copyProperties(image, ['system:time_start']);
    };
    const maskedCollection = collection.map(maskQuality);

    // Create a mean composite for the year
    const meanImage = maskedCollection.mean();

    const scale = 3000; // Use a coarse scale for regional average to avoid timeout

    // Calculate the number of valid pixels
    const pixelCount = meanImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: sichuanBasin,
      scale: scale,
      maxPixels: 1e9
    }).get(aodBand).getInfo();

    if (!pixelCount || pixelCount === 0) {
      return { mean: null, pixels: 0, images: collectionSize, year: year };
    }

    // Calculate the mean AOD value
    const meanAod = meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: sichuanBasin,
      scale: scale,
      maxPixels: 1e9
    }).get(aodBand).getInfo();

    return { mean: meanAod, pixels: pixelCount, images: collectionSize, year: year };
  };

  // 3. Calculation for each period
  const aod2006 = getMeanAod(startYear);
  const aod2020 = getMeanAod(endYear);

  // 4. Validation & Final Answer
  if (aod2006.images === 0 || aod2020.images === 0) {
    console.log(`Image collection for 2006: ${aod2006.images}`);
    console.log(`Image collection for 2020: ${aod2020.images}`);
    console.log("Empty collection for one or both years.");
    console.log("C1");
    return;
  }

  if (aod2006.pixels === 0 || aod2020.pixels === 0) {
    console.log(`Valid pixels in 2006: ${aod2006.pixels}`);
    console.log(`Valid pixels in 2020: ${aod2020.pixels}`);
    console.log("No valid pixels found after quality masking.");
    console.log("C2");
    return;
  }

  if (aod2006.mean === null || aod2020.mean === null) {
    console.log(`Mean AOD 2006: ${aod2006.mean}`);
    console.log(`Mean AOD 2020: ${aod2020.mean}`);
    console.log("Calculation failed, result is null.");
    console.log("C3");
    return;
  }

  console.log(`Sichuan Basin Mean AOD (2006): ${aod2006.mean.toFixed(4)} (from ${aod2006.images} images, ${aod2006.pixels} pixels)`);
  console.log(`Sichuan Basin Mean AOD (2020): ${aod2020.mean.toFixed(4)} (from ${aod2020.images} images, ${aod2020.pixels} pixels)`);

  if (aod2020.mean < aod2006.mean) {
    console.log("Aerosol optical depth decreased.");
    console.log("A");
  } else {
    console.log("Aerosol optical depth did not decrease.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred during execution.");
    console.error(err);
    console.log("D");
});
